function comparisonStory(c){
 const m=c.left.input.model, time=c.time, specs=presentation().data.comparison;
 const a=CE3Comparison.analyse(m,c.pathA,specs,time),b=CE3Comparison.analyse(m,c.pathB,specs,time);
 const focus=CE3Comparison.focus(m,a,b),sides=[[c.left,a],[c.right,b]];
 const when=t=>t===null?`Inte inom ${unit()} ${time}`:`${stepTitle()} ${t}`;
 const changedFields=Object.keys(a.state).filter(field=>stable(a.state[field])!==stable(b.state[field]));
 const title=focus?(focus.guard?label(focus.guard.field,'fields'):label(focus.id,'decisions')):changedFields.length?`Tillstånd skiljer sig vid ${unit()} ${time}`:'Ingen skillnad i genomförandetid har observerats';
 let difference='';
 if(focus){
  if(focus.left!==null&&focus.right!==null){const n=Math.abs(focus.left-focus.right);difference=n?`${focus.left<focus.right?c.left.record.plan_name:c.right.record.plan_name} når detta ${duration(n)} tidigare än ${focus.left<focus.right?c.right.record.plan_name:c.left.record.plan_name}.`:'Samma tidpunkt i båda planerna.';}
  else difference=focus.left===null&&focus.right===null?`Detta uppnås inte i någon av planerna inom ${unit()} ${time}. ${time===m.clock.horizon?'Inget senare datum kan utläsas.':'Välj analysens slut för senare observationer.'}`:`Detta uppnås bara i en av planerna inom den visade tiden. ${time===m.clock.horizon?'Ett senare datum för den andra planen är inte känt.':'Välj analysens slut för senare observationer.'}`;
 }
 const different=stable(c.left.input.outcomes)!==stable(c.right.input.outcomes);
 let html=`<section class="panel story-main"><p class="eyebrow">01 · HUVUDSKILLNADEN</p><h2>${esc(title)}</h2>${focus?.guard?`<p>Vi jämför när detta gäller: ${esc(presentation().guard(focus.guard))}.</p>`:''}${focus?`<div class="story-pair">${sides.map(([r,o],i)=>`<div><span>${esc(r.record.plan_name)}</span><strong>${esc(when(i?focus.right:focus.left))}</strong></div>`).join('')}</div><p class="story-lead">${esc(difference)}</p>`:changedFields.length?stateTable(Object.fromEntries(changedFields.map(k=>[k,a.state[k]])),b.state):'<p>Se tillstånd, glapp och utgifter nedan. Lika beslutstidpunkter innebär inte att alla resultat är lika.</p>'}${focus&&!focus.defined?'<p class="hint">Urvalet visar ett beslut som saknas i en plan eller den största observerade tidsskillnaden. Underlaget anger ingen generell rangordning av vad som är viktigast.</p>':''}${focus?.guard&&(!a.focus.atEnd||!b.focus.atEnd)&&focus.left!==null&&focus.right!==null?'<p class="hint">Markören gäller inte längre i minst en plan vid den visade tidens slut. Se tillståndsdetaljerna.</p>':''}<p class="hint">Visar valda händelseordningar till ${esc(unit())} ${time}. Detta utser ingen generell vinnare.</p>${different?'<p class="story-warning"><strong>Olika externa besked.</strong> Skillnaderna kan bero på både planeringen och beskeden. Utfallet kan inte tillskrivas enbart planernas tidpunkter.</p>':''}${c.left.order_sensitive||c.right.order_sensitive?'<p class="story-warning">Ordningen mellan samtidiga händelser påverkar resultat i minst en körning. Här visas ett kontrollerat förlopp per plan. Kontrollen av alla ordningar finns under Förutsättningarna.</p>':''}</section>`;
 html+=`<section class="panel story-consequence"><p class="eyebrow">02 · KONSEKVENSEN</p><h2>Glapp mellan förändringarna</h2><p class="hint">${esc(a.spec.note||'Glapp räknas från observerade tillstånd vid tidsstegens slut.')}</p>${a.gaps.length?a.gaps.map((g,i)=>`<div class="gap-block"><h3>${esc(g.name)}</h3><p class="hint">Från: ${esc(presentation().guard(g.after))}. Tills: ${esc(presentation().guard(g.until))}.</p><div class="story-pair">${sides.map(([r,o])=>{const gap=o.gaps[i];return `<div><h4>${esc(r.record.plan_name)}</h4><p>${esc(gap.anchor===null?'Förändringen som startar glappet sker inte inom den visade tiden.':`${presentation().statement(gap.after.field,gap.anchorValue)} · ${unit()} ${gap.anchor}.`)}</p>${gap.periods.length?gap.periods.map(p=>`<p class="gap-period"><strong>${p.ongoing||p.leftCensored?'Minst ':''}${esc(duration(p.length))}</strong> ${tag(p.ongoing?(time===m.clock.horizon?'Kvarstår vid analysens slut':'Kvarstår vid vald tidpunkt'):'Avslutat',p.ongoing?'warn':'')}<br>${esc(unit())} ${p.start}${p.end===null?`–${time}, fortfarande öppet`:`–${p.end}`}${p.leftCensored?'<br>Startvillkoret gällde redan vid analysens start; glappet kan ha börjat tidigare.':''}</p>`).join(''):`<p><strong>${gap.anchor===null?'Inget glapp har kunnat börja':'Inget glapp · '+duration(0)}</strong></p>`}</div>`;}).join('')}</div></div>`).join(''):'<p>Inga verksamhetsglapp har beräknats. Det betyder inte att glapp saknas.</p>'}<p class="hint">Längd är förfluten tid, avläst vid tidsstegens slut. Ett glapp som kvarstår får inget antaget slutdatum. Förändringar inom samma tidssteg kan ses i historiken.</p></section>`;
 function whyDecision(o,id){
  const d=o.decisions.find(x=>x.id===id);if(!d)return '';
  return `<div class="why-decision"><h4>${esc(label(id,'decisions'))}</h4><p>${esc(d.ready===null?`Alla krav är inte samtidigt uppfyllda med tillräcklig budget vid något beslutstillfälle inom ${unit()} ${time}.`:`Alla krav är uppfyllda och budgeten räcker första gången vid ett beslutstillfälle ${unit()} ${d.ready}.`)} ${esc(d.executed.length?`Beslutet genomförs enligt planen ${unit()} ${d.executed.join(', ')}.`:`Beslutet genomförs inte inom ${unit()} ${time}.`)}</p>${d.blocked.length?d.blocked.map(attempt=>`<div class="blocked-attempt"><strong>Blockerat försök · ${esc(unit())} ${attempt.step}</strong><ul>${attempt.failures.map(f=>`<li>${f.field==='once_only'?'Beslutet var redan genomfört.':`Krav: ${esc(presentation().guard({field:f.field,op:f.operator,value:f.required}))}. Vid försöket: ${esc(presentation().statement(f.field,f.actual))}.<br><span class="hint">${esc(f.met===null?`Inte observerat uppfyllt efter försöket inom ${unit()} ${time}.`:`Först observerat uppfyllt efter försöket ${unit()} ${f.met}.`)}</span>`}</li>`).join('')}</ul></div>`).join(''):'<p class="hint">Inget blockerat försök för detta beslut i den visade historiken.</p>'}</div>`;
 }
 html+=`<section class="panel story-why"><p class="eyebrow">03 · VARFÖR</p><h2>Förutsättningar och faktiska försök</h2><p class="hint">Uppfyllda villkor genomför inte ett beslut automatiskt. Planen måste innehålla ett nytt försök. En uppgift om ”först uppfyllt” betyder inte att villkoret sedan alltid förblir uppfyllt.</p><div class="story-pair">${sides.map(([r,o])=>{const other=o.decisions.filter(d=>d.blocked.length&&d.id!==focus?.id);return `<div><h3>${esc(r.record.plan_name)}</h3>${focus?.id?whyDecision(o,focus.id):'<p>Ingen entydig koppling mellan huvudobservationen och ett enskilt beslut finns i underlaget.</p>'}${other.length?`<details${focus?.id?'':' open'}><summary>Övriga blockerade beslut · ${other.length}</summary>${other.map(d=>whyDecision(o,d.id)).join('')}</details>`:''}</div>`;}).join('')}</div></section>`;
 html+=`<section class="panel story-spending"><p class="eyebrow">04 · UTGIFTERNA</p><h2>Vad som faktiskt betalats</h2><p class="hint">Endast genomförda beslut får en betalning. Beloppen kommer från kostnaden i den granskade modellen. ${esc(presentation().data.budget_note||'Budgeten saknar deklarerad enhet.')}</p><div class="story-pair">${sides.map(([r,o])=>{const outgoing=o.adjustments.reduce((n,x)=>n+Math.max(0,-x.amount),0),incoming=o.adjustments.reduce((n,x)=>n+Math.max(0,x.amount),0);return `<div><h3>${esc(r.record.plan_name)}</h3>${m.budget?`<div class="spending-totals"><div><span>Spenderat totalt</span><strong>${esc(money(o.spent+outgoing))}</strong></div><div><span>Budget kvar</span><strong>${esc(money(o.remaining))}</strong></div></div><p class="hint">Beslutsbetalningar ${esc(money(o.spent))} · övriga budgetutflöden ${esc(money(outgoing))} · tillskott ${esc(money(incoming))}.</p><div class="table-scroll"><table class="payments"><thead><tr><th>${esc(stepTitle())}</th><th>Genomfört beslut</th><th>Betalning</th></tr></thead><tbody>${o.payments.filter(p=>p.amount>0).map(p=>`<tr><td>${p.step}</td><td>${esc(label(p.id,'decisions'))}</td><td>${esc(money(p.amount))}</td></tr>`).join('')||'<tr><td colspan="3">Inga beslut med betalning har genomförts.</td></tr>'}</tbody></table></div><p class="hint">${o.payments.filter(p=>p.amount===0).length} genomförda beslut utan kostnad. Blockerade och överhoppade försök är inte betalningar.</p>${o.adjustments.length?`<details><summary>Tillskott och övriga budgetförändringar</summary>${o.adjustments.map(x=>`<p>${esc(unit())} ${x.step} · ${esc(label(x.id))}: ${x.amount>0?'+':'−'}${esc(money(Math.abs(x.amount)))}</p>`).join('')}</details>`:''}`:'<p>Modellen har inget budgetkonto. Betalningar och kvarvarande budget kan därför inte redovisas.</p>'}</div>`;}).join('')}</div></section>`;
 html+=`<section class="panel story-premises"><p class="eyebrow">05 · FÖRUTSÄTTNINGARNA</p><h2>Beskeden och kontrollen bakom jämförelsen</h2><p>${different?'Planerna har olika externa besked. Detta är också en jämförelse mellan olika förutsättningar.':'Samma externa besked är valda för båda planerna.'} Samma modell och startläge har kontrollerats.</p><div class="story-pair">${sides.map(([r,o])=>`<div><h3>${esc(r.record.plan_name)}</h3><p>Analys: ${esc(unit())} ${r.input.model.clock.start}–${r.input.model.clock.horizon}. Visat till ${esc(unit())} ${time}.</p>${tag('Körning: '+r.status,'ok')} ${tag('Granskning: '+r.audit.status,'ok')}<p class="hint">${r.paths.length} händelseordningar granskade. ${r.order_sensitive?'Skillnader mellan ordningar finns.':'Inga skillnader mellan ordningar observerades.'}</p>${Object.entries(r.input.outcomes).map(([id,outcome])=>`<p><strong>${esc(label(id,'events'))}</strong><br>${esc(outcomeText(id,outcome))}</p>`).join('')||'<p>Inga externa besked i modellen.</p>'}</div>`).join('')}</div><details><summary>Välj annan tidpunkt eller händelseordning</summary><div class="result-toolbar"><label>Visa till · ${esc(unit())}<select id="compare-time">${Array.from({length:m.clock.horizon-m.clock.start+1},(_,i)=>i+m.clock.start).map(t=>`<option value="${t}"${selected(t,time)}>${t}</option>`).join('')}</select></label>${[['A',c.left,c.indexA],['B',c.right,c.indexB]].map(([side,r,idx])=>`<label>${esc(r.record.plan_name)} · händelseordning<select data-compare-path="${side}">${r.paths.map((p,i)=>`<option value="${i}"${selected(i,idx)}>Ordning ${i+1}${i===r.reference?' · modellens referens':''}</option>`).join('')}</select></label>`).join('')}</div><p class="hint">Alla fem avsnitt räknas om för den valda tiden och ordningen. En enskild ordning är inte en garanti för alla ordningar.</p></details><details><summary>Tillstånd sida vid sida</summary>${stateTable(a.state,b.state)}</details><details><summary>Tekniska detaljer, källor och full historik</summary>${sensitivity(c.left)}${sensitivity(c.right)}${technicalRaw({definitions:specs||null,plans:sides.map(([r,o],i)=>({record:r.record,input:r.input,audit:r.audit,paths:r.paths,history:(i?c.pathB:c.pathA).history}))})}</details></section>`;
 return html;
}
function compareView(){
 const ids=compareChoices(),needs=CE3Presentation.comparisonNeeds(S.p,S.runs,ids);
 let html=head('Förstå skillnaden mellan planerna.','Tidpunkter, glapp, orsaker och utgifter från granskade körningar.',saveButton());
 if(S.p.plans.length<2)return html+`<section class="panel empty"><h2>Börja med ett alternativ</h2><p>Du har en plan. Skapa en kopia och ändra tidpunkterna för att kunna jämföra två genomföranden.</p><button class="primary" data-action="duplicate-compare">Duplicera planen och ändra tidpunkterna</button></section>`;
 const [left,right]=ids.map(id=>S.p.plans.find(p=>p.id===id));
 const different=left&&right&&stable(left.outcomes)!==stable(right.outcomes);
 html+=`<section class="panel"><div class="compare-controls"><label>Vänster plan<select id="compare-left">${planOptions(ids[0])}</select></label><label>Höger plan<select id="compare-right">${planOptions(ids[1])}</select></label><button class="primary" data-action="compare" ${needs.length?'disabled':''}>Jämför körningarna</button></div><div class="comparison-readiness" role="status">${needs.length?`<p><strong>Före jämförelsen:</strong></p><ul>${needs.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><button class="small" data-tab="plans">Gå till planerna</button>`:'<p>✓ Två olika planer är redo. Historikerna granskas igen när du jämför.</p>'}${different?'<p class="story-warning">Olika externa besked är valda. Jämförelsen kommer att visa effekten av både planer och besked.</p>':''}</div></section>`;
 return html+(S.comparison?comparisonStory(S.comparison):'<section class="panel empty"><h2>Se vad som händer – och varför.</h2><p>Jämför planernas senaste granskade körningar för att se tidpunkter, förutsättningar och faktiska betalningar.</p></section>');
}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===S.tab));$('#content').innerHTML=S.tab==='project'?projectView():!S.p?requireProject():S.tab==='decisions'?decisionsView():S.tab==='plans'?plansView():compareView();}
async function refresh(){S.projects=await api('/api/projects');}
function useProject(p){S.p=p;S.planId=p.plans[0].id;S.result=null;S.path=null;S.comparison=null;S.compareIds=null;S.dirty=!p.id;S.time=p.model.clock.horizon;S.row=null;S.planPane='edit';S.showAllWeeks=false;S.weekPage=0;S.editorRows=null;S.runLimits={};S.timelinePage=0;S.timelineFilter='all';S.timelineOpen=false;S.blockPage=0;}
async function load(id,revision){const v=await api('/api/project?id='+id+(revision?'&revision='+revision:''));useProject(v.project);S.versions=v.versions;S.runs=v.runs;notify('Projektet är öppnat.');render();}
async function save(){if(!S.p)return;S.p=await api('/api/save',S.p);S.dirty=false;const v=await api('/api/project?id='+S.p.id);S.versions=v.versions;S.runs=v.runs;await refresh();notify('Sparat lokalt som version '+S.p.revision+'.');}
async function preserveDraft(){if(S.p&&S.dirty)await save();}
async function result(id){notify('Återläser och granskar sparad historik…');S.path=null;S.result=await api(`/api/result?project=${S.p.id}&run=${id}`);S.pathIndex=S.result.reference??0;S.time=S.result.input.model.clock.horizon;S.row=null;if(S.result.audit.status==='PASS')S.path=await api(`/api/path?project=${S.p.id}&run=${id}&index=${S.pathIndex}`);notify('Körning: '+S.result.status+' · granskning: '+S.result.audit.status);}
async function download(){await preserveDraft();const exported=await api('/api/export',{project:S.p.id});notify('Projektet har exporterats till '+exported.path+' · '+Math.round(exported.bytes/1024)+' kB. Välj filen via Importera projekt för att återöppna den.');}
const actions={
 'plan-pane'(b){return changePlanPane(b.dataset.pane);},
 'week-prev'(){S.weekPage--;render();},'week-next'(){S.weekPage++;render();},
 'timeline-prev'(){S.timelinePage--;render();},'timeline-next'(){S.timelinePage++;render();},
 'block-prev'(){S.blockPage--;render();},'block-next'(){S.blockPage++;render();},
 async save(){await save();render();},
 open(){S.replaceModel=false;$('#model-file').click();},
 'replace-model'(){S.replaceModel=true;$('#model-file').click();},
 import(){$('#project-file').click();},
 async example(b){await preserveDraft();useProject(await api('/api/example?name='+b.dataset.name));S.runs=[];S.versions=[];notify('Exemplet är öppnat. Välj externa besked före körning.');render();},
 async load(b){await preserveDraft();await load(b.dataset.id);},
 async version(b){await preserveDraft();await load(S.p.id,Number(b.dataset.revision));},
 async refresh(){await refresh();render();},
 export:download,
 'new-plan'(){const p={id:crypto.randomUUID().replaceAll('-',''),name:'Plan '+(S.p.plans.length+1),script:{schema_version:'ce3-script/1',source:'Lokal användarplan',steps:{}},outcomes:{}};S.p.plans.push(p);S.planId=p.id;S.result=null;S.path=null;S.planPane='edit';S.weekPage=0;dirty();render();},
 'duplicate-compare'(){actions.duplicate();S.tab='plans';notify('Ändra tidpunkterna i kopian och pröva sedan båda planerna.');render();},
 duplicate(){const p=clone(currentPlan());p.id=crypto.randomUUID().replaceAll('-','');p.name+=' · kopia';S.p.plans.push(p);S.planId=p.id;S.result=null;S.path=null;S.planPane='edit';S.weekPage=0;dirty();render();},
 'add-row'(){const rows=entries();const decision=Object.keys(S.p.model.decisions)[0];if(!decision)throw {message:'Modellen har inga beslut.'};rows.push({step:rows.at(-1)?.step??S.p.model.clock.start,decision,mode:'attempt'});setEntries(rows);if(S.showAllWeeks)S.weekPage=Math.floor((rows.at(-1).step-S.p.model.clock.start)/12);render();},
 remove(b){const rows=entries();rows.splice(Number(b.dataset.index),1);setEntries(rows);render();},
 up(b){move(Number(b.dataset.index),-1);},down(b){move(Number(b.dataset.index),1);},
 async run(){const limits={...S.config.limits,...S.runLimits};await save();notify('Spelar upp planen och alla eventordningar. Därefter återläses och granskas historiken…');$('#content').classList.add('busy');const record=await api('/api/run',{project:S.p.id,revision:S.p.revision,plan:S.planId,limits});S.runs.push(record);await result(record.id);S.planPane='result';S.timelinePage=0;S.blockPage=0;render();$('#run-result')?.scrollIntoView({block:'start'});},
 'inspect-row'(b){S.row=Number(b.dataset.index);render();$('#row-inspection')?.scrollIntoView({block:'start'});},
 'step-end'(){S.row=null;render();},
 async compare(){const needs=CE3Presentation.comparisonNeeds(S.p,S.runs,compareChoices());if(needs.length)throw {message:needs.join(' ')};const left=latest($('#compare-left').value),right=latest($('#compare-right').value);if(!left||!right)throw {message:'Kör båda planerna innan du jämför.'};notify('Återgranskar båda körningarna och kontrollerar jämförbarhet…');const c=await api(`/api/compare?project=${S.p.id}&left=${left.id}&right=${right.id}&allow_different_outcomes=true`);if(!sameRunInput(c.left)||!sameRunInput(c.right))throw {message:'En plan eller modell har ändrats. Kör om båda aktuella planerna före jämförelse.'};c.indexA=c.left.reference;c.indexB=c.right.reference;c.time=c.left.input.model.clock.horizon;[c.pathA,c.pathB]=await Promise.all([api(`/api/path?project=${S.p.id}&run=${left.id}&index=${c.indexA}`),api(`/api/path?project=${S.p.id}&run=${right.id}&index=${c.indexB}`)]);S.comparison=c;notify('Båda historikerna är granskade och har jämförbara indata.');render();}
};
function move(i,delta){const rows=entries(),j=i+delta;if(rows[j]&&rows[j].step===rows[i].step){[rows[i],rows[j]]=[rows[j],rows[i]];setEntries(rows);render();}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab){if(S.busy)return;syncForm();S.tab=b.dataset.tab;render();window.scrollTo(0,0);return;}if(actions[b.dataset.action])task(()=>actions[b.dataset.action](b));});
document.addEventListener('change',e=>task(async()=>{const el=e.target;if(el.id==='show-all-weeks'){S.showAllWeeks=el.checked;S.weekPage=0;render();}else if(el.id==='week-jump'){S.weekPage=Math.floor((Number(el.value)-S.p.model.clock.start)/12);render();}else if(el.id==='timeline-filter'){S.timelineFilter=el.value;S.timelinePage=0;render();}else if(el.id==='project-name'){S.p.name=el.value;dirty();}else if(el.id==='plan-name'){currentPlan().name=el.value;dirty();render();}else if(el.dataset.presentGroup!==undefined){render();}else if(el.dataset.row!==undefined){render();}else if(el.dataset.outcome){if(el.value)currentPlan().outcomes[el.dataset.outcome]=el.value;else delete currentPlan().outcomes[el.dataset.outcome];dirty();render();}else if(el.id==='compare-left'||el.id==='compare-right'){S.compareIds=[$('#compare-left').value,$('#compare-right').value];S.comparison=null;render();}else if(el.id==='active-plan'){S.planId=el.value;S.result=null;S.path=null;const r=latest(S.planId);S.weekPage=0;S.blockPage=0;S.timelinePage=0;if(r&&S.planPane==='result')await result(r.id);render();}else if(el.id==='saved-run'&&el.value){await result(el.value);render();}else if(el.id==='path-index'){S.pathIndex=Number(el.value);S.row=null;S.path=await api(`/api/path?project=${S.p.id}&run=${S.result.record.id}&index=${S.pathIndex}`);render();}else if(el.id==='result-time'){S.time=Math.min(S.result.input.model.clock.horizon,Math.max(S.result.input.model.clock.start,Number(el.value)));S.row=null;render();}else if(el.id==='compare-time'){S.comparison.time=Math.min(S.comparison.left.input.model.clock.horizon,Math.max(S.comparison.left.input.model.clock.start,Number(el.value)));render();}else if(el.dataset.comparePath){const c=S.comparison,side=el.dataset.comparePath;c['index'+side]=Number(el.value);c['path'+side]=await api(`/api/path?project=${S.p.id}&run=${side==='A'?c.left.record.id:c.right.record.id}&index=${el.value}`);render();}else if(el.id==='model-file'&&el.files[0]){const p=await api('/api/open',{text:await el.files[0].text()});if(S.replaceModel){S.p.model=p.model;S.p.sources=p.sources;S.p.model_identity=p.model_identity;S.p.presentation={...S.p.presentation,...p.presentation};S.p.plans.forEach(plan=>plan.outcomes={});S.result=null;S.path=null;dirty();notify('Modellen har bytts. Välj externa utfall på nytt och kontrollera planernas beslut.');}else{await preserveDraft();useProject(p);S.runs=[];S.versions=[];}el.value='';render();}else if(el.id==='project-file'&&el.files[0]){await preserveDraft();const p=await api('/api/import',{text:await el.files[0].text()});await refresh();await load(p.id);el.value='';notify('Projektet har importerats som en ny lokal kopia. Historikerna har återgranskats.');}}));
document.addEventListener('keydown',e=>{if(e.target.getAttribute('role')!=='tab'||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();task(()=>changePlanPane(e.key==='Home'?'edit':e.key==='End'?'result':S.planPane==='edit'?'result':'edit'));});
document.addEventListener('input',e=>{if(!S.busy&&(e.target.matches('[data-field], [data-present-group]')||['project-name','plan-name'].includes(e.target.id)))syncForm();});
window.addEventListener('beforeunload',e=>{if(S.dirty){e.preventDefault();e.returnValue='';}});
task(async()=>{S.config=await api('/api/config');await refresh();render();});
